// Generated by tools/gen_quest_voices.py from src/narration-quests-text.json (ajan:quests). Do not edit by hand.
// Adds story/quest lines to BABA.Narration (tr-TR-AhmetNeural) and BABA.NarrationEN (en-US-SteffanNeural).
window.BABA = window.BABA || {};
(function (B) {
  B.Narration = B.Narration || {}; B.NarrationEN = B.NarrationEN || {};
  var TR = {"story1":{"text":"Nakil emrinde Kara Kadı’nın mührü var. Seni canlı istiyor. Gardiyanlar onun için çalışıyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":8.76,"chapter":1,"audio":""},"truth1":{"text":"Gardiyanın son sözü bir uyarı: Liman efendisi seni bekliyor. Kara Kadı kaçışını öğrendi.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.368,"chapter":1,"audio":""},"rescue1":{"text":"Derviş güvenli yere ulaştı. Matarasını sana bıraktı.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.088,"chapter":1,"audio":""},"hunt1":{"text":"Kefen Dokuyucu düştü. Bir daha yaşayan birini saramayacak.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.472,"chapter":1,"audio":""},"pages1":{"text":"Üç kayıt aynı yolu gösteriyor: mezar, liman, harabeler. Hepsinde Kara Kadı’nın mührü var.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.584,"chapter":1,"audio":""},"story2":{"text":"Gemilerin güvertesi boş. Esirler aşağıda zincirli. Liman efendisi onları harabelere gönderiyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":9.504,"chapter":2,"audio":""},"truth2":{"text":"Liman efendisi son nefesinde harabeleri işaret ediyor. Kadı’nın kurbanları orada bekliyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.272,"chapter":2,"audio":""},"rescue2":{"text":"Kerem fenere ulaştı. Artık geminin zincirlerinden uzakta.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.568,"chapter":2,"audio":""},"hunt2":{"text":"Tuz İçindeki Yeminli düştü. Üzerinde bir anahtar ve sevkiyat kaydı var.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.168,"chapter":2,"audio":""},"pages2":{"text":"Gemi kayıtları aynı emri taşıyor: Esirler canlı teslim edilecek. Alıcı, Kara Kadı.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.416,"chapter":2,"audio":""},"story3":{"text":"Taşın içindeki sesler yardım istiyor. Kadı onları bu mağaraya bağlamış. Zincirlerin dövüldüğü ocak daha derinde.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":9.96,"chapter":3,"audio":""},"truth3":{"text":"Bekçinin zırhında ocağın damgası var. Bu zincirleri yapan usta aşağıda.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.48,"chapter":3,"audio":""},"rescue3":{"text":"Kör taşçı güvenli yere ulaştı. Bildiği geçidi sana gösterdi.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.616,"chapter":3,"audio":""},"hunt3":{"text":"Kehanetçi Ulvi düştü. Kadı’nın avcıları bir rehber daha kaybetti.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.76,"chapter":3,"audio":""},"pages3":{"text":"Kayıtlarda kurtuluş yazıyor. Duvarların içinde yaşayan insanlar var. Kadı’nın vaadi bu.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":8.52,"chapter":3,"audio":""},"story4":{"text":"Esirler ateşin başında çalıştırılıyor. Ocak durursa Kadı yeni zincir yaptıramaz. Önce onları çıkar.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":9.552,"chapter":4,"audio":""},"truth4":{"text":"Ustanın anahtarı son kapıyı açıyor. Ardında Kara Kadı’nın mahkemesi var.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.312,"chapter":4,"audio":""},"rescue4":{"text":"Yusuf zincir örsünden uzaklaştı. Son işini senin silahın için yapıyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.168,"chapter":4,"audio":""},"hunt4":{"text":"Kül Veziri düştü. Üzerindeki mühür, Kadı’nın mahkemesine ait.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.832,"chapter":4,"audio":""},"pages4":{"text":"Demir hesabı, esir hesabıyla aynı defterde. Kadı için insan da zincir de bir yük.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.104,"chapter":4,"audio":""},"story5":{"text":"Kadı kurbanların soluğuyla ömrünü uzatıyor. Son esirler hâlâ bağlı. Onları çıkar, sonra hesabını gör.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":10.032,"chapter":5,"audio":""},"ch5Intro":{"text":"Seni gömdüren adam burada. Bu kez mahkemesine zincirsiz geldin.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.0,"chapter":5,"audio":""},"ch5Checkpoint":{"text":"Son kapıya geldin. Arkanda açtığın yol, önünde Kara Kadı var.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.0,"chapter":5,"audio":""},"ch5Boss":{"text":"Kara Kadı. Seni canlı gömen adam. Onun düzenini bitir.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.504,"chapter":5,"audio":""},"ch5Win":{"text":"Kadı düştü. Son zincirleri kır ve esirleri gün ışığına çıkar.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.448,"chapter":5,"audio":""},"ch5Death":{"text":"Seni bir kez gömdüler. İkinci kez izin verme. Kalk.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.312,"chapter":5,"audio":""},"questSeals":{"text":"Kurban düzeninin bağları koptu. Kadı’nın kapısı açılıyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.064,"chapter":5,"audio":""},"questSelvi":{"text":"Son esirlerin zincirleri çözüldü. Çıkış yolu onların da yolu.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.448,"chapter":5,"audio":""},"selviFreed":{"text":"Esirler ayağa kalkıyor. Bahtiyar yolu gösteriyor: Yürüyebilen, benimle gelsin.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.248,"chapter":5,"audio":""},"hunt5":{"text":"Mürekkep Celladı düştü. Kadı’nın son avcısı sustu.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.944,"chapter":5,"audio":""},"pages5":{"text":"Emirde senin adın var: Bahtiyar. Canlı gömülecek. Altındaki mühür Kara Kadı’nın.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":8.28,"chapter":5,"audio":""},"endingName":{"text":"Kara Kadı öldü. Zincirler düştü. Bahtiyar esirlerle birlikte gün ışığına çıkıyor. Arkalarında mezar ilk kez sessiz. Önlerinde açık bir yol var.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":15.504,"chapter":5,"audio":""},"endingBurn":{"text":"Kara Kadı öldü. Zincirler düştü. Bahtiyar esirlerle birlikte gün ışığına çıkıyor. Arkalarında mezar ilk kez sessiz. Önlerinde açık bir yol var.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":15.504,"chapter":5,"audio":""},"endingQuill":{"text":"Kara Kadı öldü. Zincirler düştü. Bahtiyar esirlerle birlikte gün ışığına çıkıyor. Arkalarında mezar ilk kez sessiz. Önlerinde açık bir yol var.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":15.504,"chapter":5,"audio":""},"leanMercy":{"text":"Açtığın hücrelerin ardından ayak sesleri geliyor. Kurtulanlar yolunu takip ediyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.768,"chapter":5,"audio":""},"leanWrath":{"text":"Kırdığın her zincir, Kadı’nın elinden bir güç daha alıyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":3.864,"chapter":5,"audio":""}};
  var EN = {"story1":{"text":"The transport order bears the Black Qadi’s seal. He wants you alive. The guards serve him.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.248,"chapter":1,"audio":""},"truth1":{"text":"The warden’s last words are a warning: the port master awaits you. The Black Qadi knows you escaped.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.296,"chapter":1,"audio":""},"rescue1":{"text":"Dervish has reached safety. He left his flask for you.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.152,"chapter":1,"audio":""},"hunt1":{"text":"The Shroud Weaver has fallen. He will wrap no more living bodies.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.92,"chapter":1,"audio":""},"pages1":{"text":"Three records reveal the same route: grave, port, ruins. All bear the Black Qadi’s seal.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.32,"chapter":1,"audio":""},"story2":{"text":"The decks are empty. The prisoners are chained below. The port master sends them to the ruins.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.032,"chapter":2,"audio":""},"truth2":{"text":"With his final breath, the port master points toward the ruins. The Qadi’s victims wait there.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":6.888,"chapter":2,"audio":""},"rescue2":{"text":"Kerem has reached the lantern. He is beyond the ship’s chains now.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.848,"chapter":2,"audio":""},"hunt2":{"text":"The Saltbound Oathkeeper has fallen. He carried a key and a transport record.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.856,"chapter":2,"audio":""},"pages2":{"text":"The ship records carry the same order: deliver the prisoners alive. The buyer is the Black Qadi.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.032,"chapter":2,"audio":""},"story3":{"text":"Voices inside the stone cry for help. The Qadi bound them to this cavern. The forge that made their chains lies deeper.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":9.168,"chapter":3,"audio":""},"truth3":{"text":"The warden’s armor bears the forge mark. The master who made these chains is below.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":6.12,"chapter":3,"audio":""},"rescue3":{"text":"The blind mason has reached safety. He showed you a passage he knew.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.064,"chapter":3,"audio":""},"hunt3":{"text":"Ulvi the Seer has fallen. The Qadi’s hunters have lost another guide.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.16,"chapter":3,"audio":""},"pages3":{"text":"The records promise salvation. Living people are sealed inside the walls. This is the Qadi’s promise.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.992,"chapter":3,"audio":""},"story4":{"text":"Prisoners are forced to work beside the fire. Stop the forge, and the Qadi gets no new chains. Get them out first.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":9.672,"chapter":4,"audio":""},"truth4":{"text":"The master’s key opens the final gate. Beyond it lies the Black Qadi’s court.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.808,"chapter":4,"audio":""},"rescue4":{"text":"Yusuf has left the chain anvil. His last work is for your weapon.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.04,"chapter":4,"audio":""},"hunt4":{"text":"The Ash Vizier has fallen. His seal belongs to the Qadi’s court.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.064,"chapter":4,"audio":""},"pages4":{"text":"Iron and prisoners are counted in the same ledger. To the Qadi, people and chains are only cargo.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":6.912,"chapter":4,"audio":""},"story5":{"text":"The Qadi extends his life with his victims’ breath. The last prisoners are still bound. Free them, then settle your score.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":9.192,"chapter":5,"audio":""},"ch5Intro":{"text":"The man who had you buried is here. This time you enter his court unchained.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.568,"chapter":5,"audio":""},"ch5Checkpoint":{"text":"You have reached the final gate. Behind you lies the road you opened. Ahead stands the Black Qadi.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.56,"chapter":5,"audio":""},"ch5Boss":{"text":"The Black Qadi. The man who buried you alive. End his reign.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.64,"chapter":5,"audio":""},"ch5Win":{"text":"The Qadi has fallen. Break the last chains and lead the prisoners into daylight.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.736,"chapter":5,"audio":""},"ch5Death":{"text":"They buried you once. Do not let them do it again. Rise.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.352,"chapter":5,"audio":""},"questSeals":{"text":"The bonds of the sacrificial rite are broken. The Qadi’s gate is opening.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.328,"chapter":5,"audio":""},"questSelvi":{"text":"The last prisoners’ chains are broken. Your way out is theirs as well.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.16,"chapter":5,"audio":""},"selviFreed":{"text":"The prisoners rise. Bahtiyar points the way: If you can walk, come with me.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.928,"chapter":5,"audio":""},"hunt5":{"text":"The Ink Executioner has fallen. The Qadi’s last hunter is silent.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.352,"chapter":5,"audio":""},"pages5":{"text":"Your name is on the order: Bahtiyar. To be buried alive. Beneath it lies the Black Qadi’s seal.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.752,"chapter":5,"audio":""},"endingName":{"text":"The Black Qadi is dead. The chains have fallen. Bahtiyar leads the prisoners into daylight. Behind them, the grave is silent at last. An open road lies ahead.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":13.488,"chapter":5,"audio":""},"endingBurn":{"text":"The Black Qadi is dead. The chains have fallen. Bahtiyar leads the prisoners into daylight. Behind them, the grave is silent at last. An open road lies ahead.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":13.488,"chapter":5,"audio":""},"endingQuill":{"text":"The Black Qadi is dead. The chains have fallen. Bahtiyar leads the prisoners into daylight. Behind them, the grave is silent at last. An open road lies ahead.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":13.488,"chapter":5,"audio":""},"leanMercy":{"text":"Footsteps follow you from the cells you opened. The freed prisoners follow your road.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.76,"chapter":5,"audio":""},"leanWrath":{"text":"Every chain you break takes more power from the Qadi.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":3.264,"chapter":5,"audio":""}};
  Object.keys(TR).forEach(function (k) { if (!B.Narration[k]) B.Narration[k] = TR[k]; });
  Object.keys(EN).forEach(function (k) { if (!B.NarrationEN[k]) B.NarrationEN[k] = EN[k]; });
})(window.BABA);
